"""Fixed RGB sensitivity audit; channel alternatives never overwrite the IFU candidate."""
import cv2
from .reader_measurement import local_measure
from .rules import classify


def optical_audit(window,project,green):
    channels = {}
    for name,index in [('R',2),('G',1),('B',0)]:
        try:
            measurement = green if name=='G' else local_measure(cv2.merge([window[:,:,index]]*3),project)
            pred = classify(measurement['c'],measurement['t'],measurement['c_present'],None)
            channels[name] = dict(status='ok',c=measurement['c'],t=measurement['t'],
                noise=measurement['noise'],threshold=measurement['threshold'],ratio=pred['ratio'],
                candidate=pred['image_result'],positions=measurement['positions'])
        except Exception as exc:
            channels[name] = dict(status='unavailable',error_type=type(exc).__name__)
    candidates = [v['candidate'] for v in channels.values() if v['status']=='ok']
    return dict(version='rgb-sensitivity-20261018-v1',channels=channels,
        complete=len(candidates)==3,consistent=len(candidates)==3 and len(set(candidates))==1,
        decision_role='diagnostic_only',scope='channel sensitivity, not biological ground truth or optical calibration')

