"""Only the supplied IFU semantics. Optical presence thresholds are experimental."""
import math

IFU = {
    "id": "ruisen-lead-RS-2026-01A",
    "title": "重金属铅胶体金快速检测卡使用说明书",
    "document_sha256": "5bfdf94e57f4b6b9303381a2da753d9469a3c9272a9a5306dea9a538277ad584",
    "mechanism": "competitive",
    "negative": "T线显色比C线深或者一样深",
    "positive": "T线显色比C线浅或者T线不显色",
    "invalid": "C线不显色",
    "read_min_seconds": 300,
    "read_max_seconds": 480,
    "time_text": "5～8min根据示意图判定结果，其他时间判读无效。",
    "sections": ["9（5）", "10"],
}


def classify(c, t, c_present, elapsed_seconds=None, geometry_ok=True):
    if not geometry_ok or c is None or t is None:
        return {"image_result": None, "final_result": None, "rule_status": "unmeasurable"}
    if not math.isfinite(c) or not math.isfinite(t) or c < 0 or t < 0:
        raise ValueError("Non-finite or negative line intensity")
    image_result = "invalid" if not c_present else ("negative" if t >= c else "positive")
    if elapsed_seconds is None:
        return {"image_result": image_result, "final_result": None,
                "rule_status": "time_unverified", "ratio": t / c if c > 0 else None}
    if not math.isfinite(float(elapsed_seconds)) or elapsed_seconds < 0:
        raise ValueError("Invalid elapsed time")
    in_time = IFU["read_min_seconds"] <= elapsed_seconds <= IFU["read_max_seconds"]
    return {"image_result": image_result, "final_result": image_result if in_time else "invalid",
            "rule_status": "within_time" if in_time else "outside_time",
            "ratio": t / c if c > 0 else None}
